9	/**
10	 * Assigns a newly built owner its {@code customerCode}, formatted
11	 * {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is the upper-cased first three letters of
12	 * the owner's city, LAST3 the upper-cased first three letters of its last name and NNNN
13	 * a per-city 4-digit zero-padded sequence equal to one more than the owners already in
14	 * that city (e.g. {@code LON-SMI-0007}). Runs before {@link SaveOwner} and mutates the
15	 * built owner in place, so the code is stored and returned with the owner.
16	 */
17	public class AssignCustomerCode {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        long ownersInCity = Cities.countIn(ownerRepository, owner.getCity());
21	        owner.setCustomerCode(customerCode(owner.getCity(), owner.getLastName(), ownersInCity + 1));
22	    }
23	
24	    private static String customerCode(String city, String lastName, long sequence) {
25	        return String.format("%s-%s-%04d", prefix(city), prefix(lastName), sequence);
26	    }
27	
28	    /** Upper-cased first three letters of the value, used as a code segment. */
29	    private static String prefix(String value) {
30	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
31	    }
32	}
