1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * Shared address normalization for the owner pipelines: trim, collapse internal
8	 * whitespace, upper-case, and expand common street-type abbreviations
9	 * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}, matched whole-word).
10	 *
11	 * <p>Used by {@link ValidateOwnerFields} so a created owner is stored and returned
12	 * with the canonical address (and the required-field check rejects an address that is
13	 * blank once normalized), and by {@link Households} so duplicate detection and the
14	 * shared household id compare addresses in that same canonical form. The transform is
15	 * idempotent, so re-normalizing an already-normalized address is a no-op.
16	 */
17	final class AddressNormalizer {
18	
19	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
20	
21	    private AddressNormalizer() {
22	    }
23	
24	    /**
25	     * @return the canonical form of {@code address}, or {@code ""} when it is null or
26	     *         blank (so callers can treat a blank-after-normalization address uniformly).
27	     */
28	    static String normalize(String address) {
29	        if (address == null) {
30	            return "";
31	        }
32	        String collapsed = WHITESPACE.matcher(address.strip()).replaceAll(" ").toUpperCase(Locale.ROOT);
33	        if (collapsed.isEmpty()) {
34	            return "";
35	        }
36	        String[] tokens = collapsed.split(" ");
37	        StringBuilder normalized = new StringBuilder(collapsed.length());
38	        for (String token : tokens) {
39	            if (normalized.length() > 0) {
40	                normalized.append(' ');
41	            }
42	            normalized.append(expand(token));
43	        }
44	        return normalized.toString();
45	    }
46	
47	    /** Expand a single street-type abbreviation to its full word, else leave it unchanged. */
48	    private static String expand(String token) {
49	        switch (token) {
50	            case "ST":
51	                return "STREET";
52	            case "RD":
53	                return "ROAD";
54	            case "AVE":
55	                return "AVENUE";
